import{_ as t,o as e,a as o,b as c}from"./app.BZuKQ50m.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"基础定义","link":"/api/SIMD-API/c_api/defs/defs"},{"text":"枚举","link":"/api/SIMD-API/c_api/defs/enum/enum"},{"text":"asc_quant_mode","link":"/api/SIMD-API/c_api/defs/enum/asc_quant_mode"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/defs/enum/asc_quant_mode.md","filePath":"api/SIMD-API/c_api/defs/enum/asc_quant_mode.md","outlineHeaders":[{"level":2,"title":"类型别名具体定义","slug":"类型别名具体定义","link":"#类型别名具体定义"},{"level":2,"title":"枚举值详解","slug":"枚举值详解","link":"#枚举值详解"}],"lastUpdated":1789526249000}'),a={name:"api/SIMD-API/c_api/defs/enum/asc_quant_mode.md"};function r(l,d,n,_,s,i){return e(),o("div",null,[...d[0]||(d[0]=[c(`<div><article class="markdown-body"><h1>asc_quant_mode</h1><p><code>asc_quant_mode</code>用于表示L0C Buffer数据搬出时的类型转换或量化模式，作为矩阵搬出接口中<code>quant_pre_mode</code>参数的类型。</p><p>头文件路径为：<code>&quot;c_api/defs/enum.h&quot;</code>。</p><h2 id="类型别名具体定义">类型别名具体定义<a class="header-anchor" href="#类型别名具体定义">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">using</span><span class="w"> </span><span class="n">asc_quant_mode</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">QuantMode_t</span><span class="p">;</span>
</code></pre></div><p><code>asc_quant_mode</code>与<code>QuantMode_t</code>具有相同的枚举值。<code>QuantMode_t</code>由编译器环境提供，枚举项未显式指定底层整数值。</p><h2 id="枚举值详解">枚举值详解<a class="header-anchor" href="#枚举值详解">​</a></h2><p>不同产品型号支持的量化模式不同，具体接口对枚举值的支持范围也可能不同，使用时请以对应接口中<code>quant_pre_mode</code>参数的说明为准。当前产品支持情况如下：</p><div data-filter="910b"><ul><li>针对Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持的枚举值：<code>NoQuant</code>、<code>F322F16</code>、<code>F322BF16</code>、<code>DEQF16</code>、<code>VDEQF16</code>、<code>QF322B8_PRE</code>、<code>VQF322B8_PRE</code>、<code>REQ8</code>、<code>VREQ8</code>。部分矩阵搬出接口还支持<code>REQ4</code>、<code>VREQ4</code>、<code>QF322S4_PRE</code>和<code>VQF322S4_PRE</code>。</li></ul></div><div data-filter="A3"><ul><li>针对Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持的枚举值：<code>NoQuant</code>、<code>F322F16</code>、<code>F322BF16</code>、<code>DEQF16</code>、<code>VDEQF16</code>、<code>QF322B8_PRE</code>、<code>VQF322B8_PRE</code>、<code>REQ8</code>、<code>VREQ8</code>。部分矩阵搬出接口还支持<code>REQ4</code>、<code>VREQ4</code>、<code>QF322S4_PRE</code>和<code>VQF322S4_PRE</code>。</li></ul></div><div data-filter="950"><ul><li><p>针对Ascend 950PR/Ascend 950DT，下表列出的全部枚举值。</p><p><strong>表1</strong> 枚举值说明</p><table><thead><tr><th>枚举值</th><th>说明</th></tr></thead><tbody><tr><td>NoQuant</td><td>不开启量化功能。</td></tr><tr><td>F322F16</td><td>将<code>float</code>转换为<code>half</code>。</td></tr><tr><td>F322BF16</td><td>将<code>float</code>转换为<code>bfloat16_t</code>。</td></tr><tr><td>DEQF16</td><td>将<code>int32_t</code>按Scalar量化参数量化为<code>half</code>。</td></tr><tr><td>VDEQF16</td><td>将<code>int32_t</code>按Tensor量化参数量化为<code>half</code>。</td></tr><tr><td>REQ4</td><td>将<code>int32_t</code>按Scalar量化参数量化为<code>int4b_t</code>。</td></tr><tr><td>VREQ4</td><td>将<code>int32_t</code>按Tensor量化参数量化为<code>int4b_t</code>。</td></tr><tr><td>QF322B8_PRE</td><td>将<code>float</code>按Scalar量化参数量化为<code>int8_t</code>或<code>uint8_t</code>。</td></tr><tr><td>VQF322B8_PRE</td><td>将<code>float</code>按Tensor量化参数量化为<code>int8_t</code>或<code>uint8_t</code>。</td></tr><tr><td>REQ8</td><td>将<code>int32_t</code>按Scalar量化参数量化为<code>int8_t</code>或<code>uint8_t</code>。</td></tr><tr><td>VREQ8</td><td>将<code>int32_t</code>按Tensor量化参数量化为<code>int8_t</code>或<code>uint8_t</code>。</td></tr><tr><td>QF322S4_PRE</td><td>将<code>float</code>按Scalar量化参数量化为<code>int4b_t</code>。</td></tr><tr><td>VQF322S4_PRE</td><td>将<code>float</code>按Tensor量化参数量化为<code>int4b_t</code>。</td></tr><tr><td>QF322FP8_PRE</td><td>将<code>float</code>按Scalar量化参数量化为<code>fp8_e4m3fn_t</code>。</td></tr><tr><td>VQF322FP8_PRE</td><td>将<code>float</code>按Tensor量化参数量化为<code>fp8_e4m3fn_t</code>。</td></tr><tr><td>QF322HIF8_PRE</td><td>将<code>float</code>按Scalar量化参数量化为<code>hifloat8_t</code>，采用Half to Away舍入。</td></tr><tr><td>VQF322HIF8_PRE</td><td>将<code>float</code>按Tensor量化参数量化为<code>hifloat8_t</code>，采用Half to Away舍入。</td></tr><tr><td>QF322HIF8_PRE_HYBRID</td><td>将<code>float</code>按Scalar量化参数量化为<code>hifloat8_t</code>，采用Hybrid舍入。</td></tr><tr><td>VQF322HIF8_PRE_HYBRID</td><td>将<code>float</code>按Tensor量化参数量化为<code>hifloat8_t</code>，采用Hybrid舍入。</td></tr><tr><td>QS322BF16_PRE</td><td>将<code>int32_t</code>按Scalar量化参数量化为<code>bfloat16_t</code>。</td></tr><tr><td>VQS322BF16_PRE</td><td>将<code>int32_t</code>按Tensor量化参数量化为<code>bfloat16_t</code>。</td></tr><tr><td>QF322F16_PRE</td><td>将<code>float</code>按Scalar量化参数量化为<code>half</code>。</td></tr><tr><td>VQF322F16_PRE</td><td>将<code>float</code>按Tensor量化参数量化为<code>half</code>。</td></tr><tr><td>QF322BF16_PRE</td><td>将<code>float</code>按Scalar量化参数量化为<code>bfloat16_t</code>。</td></tr><tr><td>VQF322BF16_PRE</td><td>将<code>float</code>按Tensor量化参数量化为<code>bfloat16_t</code>。</td></tr><tr><td>QF322F32_PRE</td><td>将<code>float</code>按Scalar量化参数量化为<code>float</code>。</td></tr><tr><td>VQF322F32_PRE</td><td>将<code>float</code>按Tensor量化参数量化为<code>float</code>。</td></tr></tbody></table></li></ul></div></article></div>`,1)])])}const F=t(a,[["render",r]]);export{f as __pageData,F as default};
